DO $$ DECLARE d text;anchor text;replacement text;BEGIN d:=pg_get_functiondef('ops.apply_private_restore(uuid,bytea,uuid)'::regprocedure);anchor:='EXECUTE format(''SELECT COALESCE(jsonb_agg(to_jsonb(t)),''''[]''''::jsonb) FROM %s t WHERE workspace_id=$1'',name) INTO records USING scope_id;';replacement:='cols:=NULL;FOR col IN SELECT attname,format_type(atttypid,atttypmod) typ FROM pg_attribute WHERE attrelid=name::regclass AND attnum>0 AND NOT attisdropped ORDER BY attnum LOOP cols:=concat_ws('','',cols,quote_literal(col.attname)||'',''||CASE WHEN col.typ=''bigint'' OR col.typ LIKE ''numeric%'' THEN format(''t.%I::text'',col.attname) ELSE format(''t.%I'',col.attname) END);END LOOP;EXECUTE format(''SELECT COALESCE(jsonb_agg(jsonb_build_object(%s)),''''[]''''::jsonb) FROM %s t WHERE workspace_id=$1'',cols,name) INTO records USING scope_id;';IF strpos(d,anchor)=0 THEN RAISE EXCEPTION 'exact recovery anchor missing';END IF;d:=replace(d,anchor,replacement);d:=replace(d,'''workspace'',to_jsonb(w)', '''workspace'',jsonb_set(to_jsonb(w),''{financial_revision}'',to_jsonb(w.financial_revision::text))');EXECUTE d;END $$;